package com.nexustools.genericui.core

import com.nexustools.genericui.component.fragment.Fragment
import com.nexustools.genericui.component.fragment.FragmentBundle
import com.nexustools.genericui.component.shell.IApplication
import com.nexustools.genericui.resources.ResourceID
import kotlin.reflect.KClass

/**
 * Resolved application metadata, window/theme settings, fragment factories, and extension/resource
 * installers generated by the GenericUI Gradle plugin for a specific backend target.
 */
data class GenericUiAppDescriptor(
    val appId: String = "com.nexustools.genericui.app",
    val appName: String = "GenericUI",
    val appVersion: String = "1.0.0",
    val windowTitle: String = appName,
    val windowWidth: Int = 1280,
    val windowHeight: Int = 800,
    val minWindowWidth: Int = 320,
    val minWindowHeight: Int = 240,
    val windowResizable: Boolean = true,
    val fullscreen: Boolean = false,
    val themeMode: String = "dark",
    val themeColor: String = "#0d6efd",
    val iconPath: String? = null,
    val iconResourceId: ResourceID? = null,
    val mainFragmentClass: KClass<out Fragment>? = null,
    val mainFragmentFactory: ((FragmentBundle?) -> Fragment)? = null,
    val applicationFactory: ((FragmentBundle?) -> IApplication)? = null,
    val fragmentRegistrations: List<Pair<KClass<out Fragment>, (FragmentBundle?) -> Fragment>> = emptyList(),
    val providerInstallers: List<() -> Unit> = emptyList(),
    val resourceRegistryInstaller: (() -> Unit)? = null,
    val precompiledStyleSheetInstaller: ((IApplication) -> Unit)? = null
)
